import json

# Read and apply fixes
with open('/workdir/data/books.json', 'r') as f:
    content = f.read()

# Apply comprehensive fix
lines = content.split('\n')
fixed_lines = []
for i, line in enumerate(lines):
    # Check if line ends with } but not },
    if line.strip().endswith('}') and not line.strip().endswith('},'):
        # Check if next line starts with {
        if i + 1 < len(lines) and lines[i+1].strip().startswith('{'):
            fixed_lines.append(line.rstrip() + ',')
        else:
            fixed_lines.append(line)
    # Check if line ends with " (string value) and next line starts with " (key)
    elif line.strip().endswith('"') and not line.strip().endswith(',"'):
        # Check if this is end of value, not end of object
        # If next line starts with " (a key), add comma
        if i + 1 < len(lines):
            next_line = lines[i+1]
            # Check if next line starts with a key pattern: quote followed by non-quote letter
            if next_line.strip().startswith('"') and not next_line.strip().startswith('"}'):
                # This might be a key, so add comma
                fixed_lines.append(line.rstrip() + ',')
            else:
                fixed_lines.append(line)
        else:
            fixed_lines.append(line)
    else:
        fixed_lines.append(line)

fixed = '\n'.join(fixed_lines)

# Write to temp file and check
with open('/workdir/test_books.json', 'w') as f:
    f.write(fixed)

print("Checking line 55-65 of fixed content...")
for i in range(54, 66):
    if i < len(fixed.split('\n')):
        print(f"Line {i+1}: {repr(fixed.split(chr(10))[i])}")

print("\nTrying to parse...")
try:
    data = json.loads(fixed)
    print(f"Success! {len(data['books'])} books")
except Exception as e:
    print(f"Error: {e}")
    # Find the problematic area
    print("\nParsing first 2000 chars to find issue...")
    try:
        partial = fixed[:2000]
        json.loads(partial)
    except Exception as e2:
        print(f"Partial parse error at: {e2}")
