import sqlite3

# Connect to database
conn = sqlite3.connect('/workdir/books.db')
cursor = conn.cursor()

# Get all data
cursor.execute('SELECT author, year, price FROM books')
rows = cursor.fetchall()

# Build data structures
authors = {}
for author, year, price in rows:
    if author not in authors:
        authors[author] = []
    authors[author].append({
        'year': int(year),
        'price': float(price)
    })

def get_era(year):
    if 1800 <= year <= 1949:
        return 'classic'
    elif 1950 <= year <= 1999:
        return 'modern'
    elif 2000 <= year <= 2025:
        return 'contemporary'
    else:
        return None

# Analyze each author
results = []
for author, books_list in authors.items():
    books_in_eras = []
    for b in books_list:
        era = get_era(b['year'])
        if era:
            books_in_eras.append((era, b['price']))

    total_books = len(books_in_eras)
    if total_books < 2:
        continue

    era_counts = {'classic': 0, 'modern': 0, 'contemporary': 0}
    era_prices = {'classic': [], 'modern': [], 'contemporary': []}
    for era, price in books_in_eras:
        era_counts[era] += 1
        era_prices[era].append(price)

    eras_present = sum(1 for c in era_counts.values() if c > 0)
    if eras_present < 2:
        continue

    classic_avg = round(sum(era_prices['classic']) / len(era_prices['classic']), 2) if era_prices['classic'] else 0.0
    modern_avg = round(sum(era_prices['modern']) / len(era_prices['modern']), 2) if era_prices['modern'] else 0.0
    contemporary_avg = round(sum(era_prices['contemporary']) / len(era_prices['contemporary']), 2) if era_prices['contemporary'] else 0.0

    eras_with_data = [e for e in ['classic', 'modern', 'contemporary'] if era_counts[e] > 0]
    earliest_era = eras_with_data[0]
    latest_era = eras_with_data[-1]

    if earliest_era == 'classic':
        earliest_avg = classic_avg
    elif earliest_era == 'modern':
        earliest_avg = modern_avg
    else:
        earliest_avg = contemporary_avg

    if latest_era == 'classic':
        latest_avg = classic_avg
    elif latest_era == 'modern':
        latest_avg = modern_avg
    else:
        latest_avg = contemporary_avg

    if earliest_avg != 0:
        inflation_rate = round(((latest_avg - earliest_avg) / earliest_avg) * 100, 1)
    else:
        inflation_rate = 0.0

    if inflation_rate > 15:
        strategy = "aggressive"
    elif inflation_rate >= 5:
        strategy = "moderate"
    else:
        strategy = "conservative"

    results.append({
        'publisher': author,
        'total_books': total_books,
        'eras_present': eras_present,
        'classic_avg': classic_avg,
        'classic_count': era_counts['classic'],
        'modern_avg': modern_avg,
        'modern_count': era_counts['modern'],
        'contemporary_avg': contemporary_avg,
        'contemporary_count': era_counts['contemporary'],
        'inflation_rate': inflation_rate,
        'pricing_strategy': strategy
    })

results.sort(key=lambda x: x['publisher'])

# Write CSV manually with proper quoting
with open('/workdir/sol.csv', 'w') as f:
    # Header (no quotes)
    f.write('publisher,total_books,eras_present,classic_avg,classic_count,modern_avg,modern_count,contemporary_avg,contemporary_count,inflation_rate,pricing_strategy\n')

    # Data rows
    for r in results:
        # Quote string fields (publisher and pricing_strategy), leave numbers unquoted
        line = f'"{r["publisher"]}",{r["total_books"]},{r["eras_present"]},{r["classic_avg"]:.2f},{r["classic_count"]},{r["modern_avg"]:.2f},{r["modern_count"]},{r["contemporary_avg"]:.2f},{r["contemporary_count"]},{r["inflation_rate"]:.1f},"{r["pricing_strategy"]}"\n'
        f.write(line)

print("CSV written successfully")

# Display content
with open('/workdir/sol.csv', 'r') as f:
    print(f.read())

conn.close()
